CREATE OR REPLACE FUNCTION private.spot_request_follow(target uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=(select auth.uid()); locked public.profiles; event text;
begin
 if me is null or me=target or not exists(select 1 from public.profiles where id=me and is_active) then raise exception 'Unauthorized'; end if;
 select * into locked from public.profiles where id=target and is_active for update;
 if not found then raise exception 'Account unavailable'; end if;
 if exists(select 1 from public.social_follows where follower_id=me and followed_id=target) then
  delete from public.social_follows where follower_id=me and followed_id=target; return 'unfollowed';
 end if;
 if exists(select 1 from public.spot_follow_requests where requester_id=me and recipient_id=target) then
  delete from public.spot_follow_requests where requester_id=me and recipient_id=target; return 'cancelled';
 end if;
 if locked.is_private then
  insert into public.spot_follow_requests(requester_id,recipient_id) values(me,target);
  event:='request:'||me||':'||target||':'||gen_random_uuid();
  insert into public.spot_activity_notifications(recipient_id,actor_id,kind,event_key) values(target,me,'follow_request',event);
  insert into public.spot_push_events(recipient_id,actor_id,kind,event_key) values(target,me,'follow_request',event);
  return 'requested';
 end if;
 insert into public.social_follows(follower_id,followed_id) values(me,target); return 'following';
end $function$

CREATE OR REPLACE FUNCTION private.spot_resolve_follow(requester uuid, accept_request boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=(select auth.uid()); event text;
begin
 if me is null or not exists(select 1 from public.profiles where id=me and is_active) then raise exception 'Unauthorized'; end if;
 perform 1 from public.profiles where id=me for update;
 perform 1 from public.spot_follow_requests where requester_id=requester and recipient_id=me for update;
 if not found then raise exception 'Request unavailable'; end if;
 delete from public.spot_follow_requests where requester_id=requester and recipient_id=me;
 if accept_request then
  if not exists(select 1 from public.profiles where id=requester and is_active) then raise exception 'Account unavailable'; end if;
  insert into public.social_follows(follower_id,followed_id) values(requester,me) on conflict do nothing;
  event:='accepted:'||requester||':'||me||':'||gen_random_uuid();
  insert into public.spot_activity_notifications(recipient_id,actor_id,kind,event_key) values(requester,me,'follow_accepted',event);
  insert into public.spot_push_events(recipient_id,actor_id,kind,event_key) values(requester,me,'follow_accepted',event);
 end if;
end $function$
